import React from 'react';
// import { ModalHeader } from 'reactstrap';
import { store } from 'index';
import { closeReportModal } from 'actions/admin/reports';
import { Dialog, DialogActions, DialogContent, makeStyles, DialogTitle } from '@material-ui/core';
import { screenHeight } from 'utils/commonFunc';
import CustomButton from 'components/CustomButton';

export const downloadFile = async (reportUrl, filename = 'new_report') => {
  const data = reportUrl;
  if (!(data instanceof Blob)) return;
  const blob = new Blob([data], { type: 'application/pdf' });
  const link = document.createElement('a');
  link.href = window.URL.createObjectURL(blob);
  link.download = `${filename}-${+new Date()}.pdf`;
  link.click();
};

const useStyles = makeStyles(() => ({
  root: {
    flexGrow: 1,
    backgroundColor: 'ivory',
  },
  dialog: {
    backgroundColor: 'white',
    minHeight: screenHeight - 10,
    width: '60%',
    height: 600,
    top: 0,
  },
}));

const ViewReportModal = props => {
  const classes = useStyles({});
  const toggle = () => {
    store.dispatch(closeReportModal());
  };

  const { isOpenReportModal, headingName, reportUrl } = props;
  const file = new Blob([reportUrl], { type: 'application/pdf' });
  const blob = URL.createObjectURL(file);

  return (
    <Dialog
      open={isOpenReportModal}
      scroll={'paper'}
      maxWidth={'md'}
      classes={{
        paper: classes.dialog,
      }}
      aria-labelledby="scroll-dialog-title"
      aria-describedby="scroll-dialog-description">
      <DialogTitle id="scroll-dialog-title" style={{ paddingBottom: 5 }}>
        <span style={{ fontSize: 20 }}>
          <b>{headingName}</b>
        </span>
      </DialogTitle>
      <DialogContent dividers={scroll === 'paper'}>
        {/* Have trouble to view Report?{' '}
        <a href="#" onClick={() => downloadFile(reportUrl, headingName)} style={{ color: 'blue' }}>
          Download here
        </a>
        <br /> */}
        <div style={{ width: '100%', height: '100%', marginTop: 10 }}>
          <iframe title="reportValue" src={blob} width="100%" height="100%" />
        </div>
      </DialogContent>
      <DialogActions>
        <CustomButton name="Close" variant="outlined" onClick={() => toggle()} />
      </DialogActions>
    </Dialog>
  );
};

export default ViewReportModal;
